@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def select_tolerance_from_list(toleranceText: str) -> None:
    """Cycles through the list of Tolerance Table names on the Tolerance Tables pane until the specified tolerance text is found
    """
    if __find_main_customize_system_settings_pane():

        # Get the text for the current tolerance selected
        current_tolerance_text_selected = CommonActions.get_all_text_via_ocr_in_object(CustomizeSettingsObjects.tolerance_Cells_List)

        if current_tolerance_text_selected is not None:
            # OCR only reads the tolerance text that is currently highlighted in blue, so click on each tolerance text
            # until the current one is found. The tooltip appears when the mouse is left hovering over the tolerance
            # text but this results in the OCR reading both the tolerance text and the tooltip text which causes issues.
            # A workaround to stop the tooltip from showing is to mouse press, hold for a short duration and release.

            while current_tolerance_text_selected != toleranceText:
                # Attempt to select the next tolerance in the list using x, y coordinates to highlight the next tolerance in the list
                if current_tolerance_text_selected is not None:
                    current_tolerance_obj = CommonActions.get_object_by_ocr_text_in_object(CustomizeSettingsObjects.tolerance_Cells_List, current_tolerance_text_selected)

                    # Select the next item in the tolerance list
                    if ("XRAY" in current_tolerance_text_selected) or (
                        "ELECTRON" in current_tolerance_text_selected and toleranceText != "XRAY") or (
                            "SERVICE 1" in current_tolerance_text_selected and toleranceText == "iCOM"):
                        # Press and hold down mouse button for a fraction longer before releasing to prevent tooltip from displaying
                       CommonActions.mouse_press_hold_and_release_with_positive_y_offset(current_tolerance_obj, yOffsetValue=20, mousePressDuration=1)

                    # Select the previous item in the tolerance list
                    elif ("ELECTRON" in current_tolerance_text_selected and toleranceText == "XRAY") or (
                        "SERVICE 1" in current_tolerance_text_selected and toleranceText != "iCOM") or (
                            "iCOM" in current_tolerance_text_selected):
                        # Press and hold down mouse button for a fraction longer before releasing to prevent tooltip from displaying
                        CommonActions.mouse_press_hold_and_release_with_negative_y_offset(current_tolerance_obj, yOffsetValue=20, mousePressDuration=1)

                    # Update current tolerance selection and check again
                    current_tolerance_text_selected = CommonActions.get_all_text_via_ocr_in_object(CustomizeSettingsObjects.tolerance_Cells_List)

                if current_tolerance_text_selected is not None:
                    if toleranceText in current_tolerance_text_selected:
                        break


